// Vectors in two dimensions: positions, velocities and forces
module math
{
    // x across, y up
    struct Vec2
    {
        float x;
        float y;
    }

    // a + b, one component at a time
    public fn add(Vec2 a, Vec2 b) -> Vec2
    {
        Vec2 r;
        r.x = a.x + b.x;
        r.y = a.y + b.y;
        return r;
    }

    // a . b: how much a points along b, times both lengths
    public fn dot(Vec2 a, Vec2 b) -> float
    {
        return a.x * b.x + a.y * b.y;
    }

    // v made s times as long
    public fn scale(Vec2 v, float s) -> Vec2
    {
        Vec2 r;
        r.x = v.x * s;
        r.y = v.y * s;
        return r;
    }

    // a - b: the step from b to a
    public fn sub(Vec2 a, Vec2 b) -> Vec2
    {
        Vec2 r;
        r.x = a.x - b.x;
        r.y = a.y - b.y;
        return r;
    }
}

